const body = $json.body ?? $json;
const pedido_id = body.pedido_id || body.orderId;
const pizzaria_id = body.pizzaria_id || body.pizzeriaId;
if (!pedido_id || !pizzaria_id) {
  return [{ json: { skip: true, reason: 'missing_ids' } }];
}
return [{ json: { skip: false, pedido_id, pizzaria_id } }];

const row = $json;

const itens = Array.isArray(row.itens) ? row.itens : (typeof row.itens === 'string' ? JSON.parse(row.itens) : []);
const itensResumo = itens.map(i => `${i.qty || 1}x ${i.name || i.nome || ''}`).join(', ');

const novoRegistro = {
  id: row.id,
  number: row.numero_pedido,
  date: row.created_at,
  items: itensResumo,
  total: Number(row.valor_total)
};

let historico = Array.isArray(row.historico_pedidos) ? row.historico_pedidos : (typeof row.historico_pedidos === 'string' ? JSON.parse(row.historico_pedidos || '[]') : []);
historico.push(novoRegistro);
if (historico.length > 10) historico = historico.slice(-10);

return [{
  json: {
    cliente_id: row.cliente_id,
    pizzaria_id: row.pizzaria_id,
    historico_json: JSON.stringify(historico),
    valor_total: Number(row.valor_total),
    endereco_entrega: row.endereco_entrega || '',
    telefone: row.telefone
  }
}];
